func TestAzureDevOpsCredentialsFileSupport(t *testing.T) {
	envBackup := backupEnvironmentVariables()
	defer restoreEnvironmentVariables(envBackup)

	preflight()
	resetGlobals()

	defer resetBackups()

	unsetEnvVarsExcept([]string{envPath, envGitBackupDir})

	tempDir := t.TempDir()

	// Write username and PAT to files
	usernameFile := filepath.Join(tempDir, "az_username")
	patFile := filepath.Join(tempDir, "az_pat")
	_ = os.WriteFile(usernameFile, []byte("fileuser"), 0o600)
	_ = os.WriteFile(patFile, []byte("filepat"), 0o600)

	_ = os.Setenv(envAzureDevOpsUserName+"_FILE", usernameFile)
	_ = os.Setenv(envAzureDevOpsPAT+"_FILE", patFile)
	_ = os.Setenv(envAzureDevOpsOrgs, "dummyorg")
	_ = os.Setenv(envAzureDevOpsBackups, "1")
	_ = os.Setenv(envAzureDevOpsCompare, "refs")

	// Should pick up credentials from files
	user, exists := GetEnvOrFile(envAzureDevOpsUserName)
	require.Equal(t, "fileuser", user)
	require.True(t, exists)

	pat, exists := GetEnvOrFile(envAzureDevOpsPAT)
	require.Equal(t, "filepat", pat)
	require.True(t, exists)

	// Now set env vars directly, which should take precedence
	_ = os.Setenv(envAzureDevOpsUserName, "envuser")
	_ = os.Setenv(envAzureDevOpsPAT, "envpat")

	user, exists = GetEnvOrFile(envAzureDevOpsUserName)
	require.Equal(t, "envuser", user)
	require.True(t, exists)

	pat, exists = GetEnvOrFile(envAzureDevOpsPAT)
	require.Equal(t, "envpat", pat)
	require.True(t, exists)
}
