package internal

import (
	"os"

	"github.com/jonhadfield/githosts-utils/v2"
	"gitlab.com/tozd/go/errors"
)

func AzureDevOps(backupDir string) *ProviderBackupResults {
	logger.Println("backing up Azure DevOps repos")

	adou, exists := GetEnvOrFile(envAzureDevOpsUserName)
	if !exists || adou == "" {
		logger.Println("Skipping Azure DevOps backup as", envAzureDevOpsUserName, "is missing")

		return &ProviderBackupResults{
			Provider: providerNameAzureDevOps,
			Results: githosts.ProviderBackupResult{
				BackupResults: []githosts.RepoBackupResults{},
				Error:         errors.New("Azure DevOps username is not set"),
			},
		}
	}

	pat, exists := GetEnvOrFile(envAzureDevOpsPAT)
	if !exists || pat == "" {
		logger.Println("Skipping Azure DevOps backup as", envAzureDevOpsPAT, "is missing")

		return &ProviderBackupResults{
			Provider: providerNameAzureDevOps,
			Results: githosts.ProviderBackupResult{
				BackupResults: []githosts.RepoBackupResults{},
				Error:         errors.New("Azure DevOps PAT is not set"),
			},
		}
	}

	bundlePassphrase, _ := GetEnvOrFile(envVarBundlePassphrase)

	azureDevOpsHost, err := githosts.NewAzureDevOpsHost(githosts.NewAzureDevOpsHostInput{
		Caller:               AppName,
		HTTPClient:           httpClient,
		BackupDir:            backupDir,
		DiffRemoteMethod:     os.Getenv(envAzureDevOpsCompare),
		UserName:             adou,
		PAT:                  pat,
		Orgs:                 getOrgsListFromEnvVar(envAzureDevOpsOrgs),
		BackupsToRetain:      getBackupsToRetain(envAzureDevOpsBackups),
		LogLevel:             getLogLevel(),
		BackupLFS:            envTrue(envAzureDevOpsBackupLFS),
		EncryptionPassphrase: bundlePassphrase,
	})
	if err != nil {
		return &ProviderBackupResults{
			Provider: providerNameAzureDevOps,
			Results: githosts.ProviderBackupResult{
				BackupResults: []githosts.RepoBackupResults{},
				Error:         errors.Wrap(err, "failed to create AzureDevOps host"),
			},
		}
	}

	return &ProviderBackupResults{
		Provider: providerNameAzureDevOps,
		Results:  azureDevOpsHost.Backup(),
	}
}
func getBackupsStats(br BackupResults) (ok, failed int) {
	if br.Results == nil {
		return 0, 0
	}

	for _, pr := range *br.Results {
		// catch error from provider
		if pr.Results.Error != nil {
			failed++

			continue
		}

		providerOk := 0

		for _, r := range pr.Results.BackupResults {
			// catch error from repository backup
			if r.Error != nil {
				failed++

				continue
			}

			ok++
			providerOk++
		}

		// If provider has credentials configured but no successful backups,
		// count it as a failure (likely authentication error)
		if providerOk == 0 && len(pr.Results.BackupResults) == 0 {
			failed++
		}
	}

	return ok, failed
}

def read_summary(report: Report, summary: Any, coverage: Any) -> dict[str, Any] | None:
    if not isinstance(summary, dict):
        report.add("summary", "schema", "`summary` must be an object")
        return None
    fields: dict[str, Any] = {}
    status = summary.get("status")
    if status not in STATUSES:
        report.add("summary.status", "status-consistency", f"`status` must be one of {list(STATUSES)}, not `{status!r}`; the reviewer selects it")
    fields["status"] = status
    if "gating" in summary:
        report.add("summary.gating", "publication-boundary", "inspect composition is advisory; omit `gating` and let the publisher select --emit-batch --event")
    for key in ("intent", "issue_fit", "coverage"):
        fields[key] = read_text(report, "summary", summary, key)
        if fields[key] is not None:
            for match in re.finditer(r"\*\*(Intent|Issue fit|Coverage|Reviewed|Mode):\*\*", mask_code(fields[key])):
                report.add(f"summary.{key}", "field-label", f"`{key}` contains the composer-owned label `{match.group(0)}` outside code")
    ambiguities = summary.get("ambiguities", [])
    if not isinstance(ambiguities, list):
        report.add("summary.ambiguities", "schema", "`ambiguities` must be a list")
        ambiguities = []
    entries: list[dict[str, str]] = []
    for index, ambiguity in enumerate(ambiguities):
        location = f"summary.ambiguities[{index}]"
        if not isinstance(ambiguity, dict):
            report.add(location, "schema", "an ambiguity must be an object")
            continue
